package com.ruoyi.common.core.domain;

import com.ruoyi.common.constant.HttpStatus;
import java.util.HashMap;

// ══ 全站统一响应结构：前端永远拿到 {code, msg, data} ══
// 继承 HashMap 的好处：JSON 序列化零配置，键即字段
public class AjaxResult extends HashMap<String, Object> {

    private static final long serialVersionUID = 1L;

    public static final String CODE_TAG = "code";   // 200 成功 / 500 失败
    public static final String MSG_TAG = "msg";
    public static final String DATA_TAG = "data";

    public AjaxResult(int code, String msg) {
        super.put(CODE_TAG, code);
        super.put(MSG_TAG, msg);
    }

    public AjaxResult(int code, String msg, Object data) {
        this(code, msg);
        if (data != null) {                          // data 为 null 时不放键，响应更干净
            super.put(DATA_TAG, data);
        }
    }

    // ── 静态工厂：语义化构造，调用方不用记 code 值 ──

    public static AjaxResult success() {
        return AjaxResult.success("操作成功");
    }

    public static AjaxResult success(Object data) {
        return AjaxResult.success("操作成功", data);
    }

    public static AjaxResult error(String msg) {
        return AjaxResult.error(HttpStatus.ERROR, msg);   // 500
    }

    public static AjaxResult error(int code, String msg) {
        return new AjaxResult(code, msg, null);
    }
}

package com.ruoyi.common.core.domain;

import java.io.Serializable;
import java.util.Date;
import java.util.HashMap;
import java.util.Map;
import com.fasterxml.jackson.annotation.JsonIgnore;

public class BaseEntity implements Serializable {

    private String searchValue;

    private String createBy;
    private Date createTime;
    private String updateBy;
    private Date updateTime;
    private String remark;

    /** 透传容器：数据权限 SQL 片段、日期范围参数都经它传递 */
    private Map<String, Object> params;

    public Map<String, Object> getParams() {
        if (params == null) {
            params = new HashMap<>();
        }
        return params;
    }

    @JsonIgnore                                   // 防止前端恶意注入 params.dataScope
    public Map<String, Object> getParams() {
        return params;
    }

    public void setCreateBy(String createBy) {
        this.createBy = createBy;
    }

    public String getCreateBy() {
        return createBy;
    }
}
